// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // hand ownership to a fuzzed actor, then that actor runs NETM()
        c.transferOwnership(actor);
        vm.prank(actor);
        c.NETM();
        // General rule: after NETM(), the owner holds exactly totalDistributed tokens.
        assertEq(c.balanceOf(actor), c.totalDistributed());
    }
}
